import{_ as e,o as l,c as a,a2 as t}from"./chunks/framework.CBWbbCW8.js";const u=JSON.parse('{"title":"常见问题排查","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/troubleshooting.md","filePath":"integrations/troubleshooting.md","lastUpdated":1785754060000}'),o={name:"integrations/troubleshooting.md"};function d(s,i,n,c,r,h){return l(),a("div",null,[...i[0]||(i[0]=[t(`<h1 id="常见问题排查" tabindex="-1">常见问题排查 <a class="header-anchor" href="#常见问题排查" aria-label="Permalink to &quot;常见问题排查&quot;">​</a></h1><p>如果接入工具失败，建议先按这一页从上到下排查。大多数问题都来自 Base URL、API Key、模型权限或客户端自动拼接路径。</p><h2 id="快速自检" tabindex="-1">快速自检 <a class="header-anchor" href="#快速自检" aria-label="Permalink to &quot;快速自检&quot;">​</a></h2><table tabindex="0"><thead><tr><th>检查项</th><th>正确状态</th></tr></thead><tbody><tr><td>Base URL</td><td><code>https://doudi.ai/v1</code></td></tr><tr><td>API Key</td><td>控制台创建，未禁用，复制完整</td></tr><tr><td>模型名</td><td>当前账号可用模型</td></tr><tr><td>余额</td><td><code>Wallet</code> 中额度充足</td></tr><tr><td>日志</td><td><code>Usage Logs</code> 中能看到请求记录</td></tr></tbody></table><h2 id="_401-unauthorized" tabindex="-1">401 Unauthorized <a class="header-anchor" href="#_401-unauthorized" aria-label="Permalink to &quot;401 Unauthorized&quot;">​</a></h2><p>常见原因：</p><ul><li>API Key 没填。</li><li>API Key 复制不完整。</li><li>Key 已被禁用或删除。</li><li>客户端要求只填 Key，但你填了 <code>Bearer xxx</code>。</li></ul><p>处理方式：</p><ol><li>到 DouDi.ai 控制台重新复制或新建 API Key。</li><li>确认客户端保存成功。</li><li>用 curl 直接请求验证 Key 是否有效。</li></ol><h2 id="_403-forbidden" tabindex="-1">403 Forbidden <a class="header-anchor" href="#_403-forbidden" aria-label="Permalink to &quot;403 Forbidden&quot;">​</a></h2><p>常见原因：</p><ul><li>当前账号没有模型或分组权限。</li><li>使用了不兼容的供应商协议。</li><li>代理层改写了 Header 或路径。</li><li>工具固定请求了不支持的接口。</li></ul><p>处理方式：</p><ol><li>换用控制台明确可用的模型。</li><li>检查是否使用 OpenAI Compatible 模式。</li><li>查看 DouDi.ai <code>Usage Logs</code> 和代理日志。</li><li>如果直连成功但客户端失败，再考虑代理层。</li></ol><h2 id="_404-not-found" tabindex="-1">404 Not Found <a class="header-anchor" href="#_404-not-found" aria-label="Permalink to &quot;404 Not Found&quot;">​</a></h2><p>常见原因：</p><ul><li>Base URL 写错。</li><li>客户端自动拼接了 <code>/v1</code>，你又手动写了一次。</li><li>把完整接口地址填到了只需要 Base URL 的地方。</li></ul><p>处理方式：</p><ul><li>如果工具要求 Base URL，填写 <code>https://doudi.ai/v1</code>。</li><li>如果工具会自动加 <code>/v1</code>，尝试填写 <code>https://doudi.ai</code>。</li><li>如果工具要求完整 URL，填写 <code>https://doudi.ai/v1/chat/completions</code>。</li></ul><h2 id="模型列表为空" tabindex="-1">模型列表为空 <a class="header-anchor" href="#模型列表为空" aria-label="Permalink to &quot;模型列表为空&quot;">​</a></h2><p>这不一定代表不能使用。部分客户端不会读取 DouDi.ai 的模型列表，或读取模型列表的接口不兼容。</p><p>处理方式：</p><ul><li>手动添加模型名。</li><li>到<a href="/diudi-docs/guide/models-pricing">模型与价格</a>页面复制模型名。</li><li>登录 DouDi.ai 控制台查看自己账号实际可用模型。</li></ul><h2 id="余额不足或消耗异常" tabindex="-1">余额不足或消耗异常 <a class="header-anchor" href="#余额不足或消耗异常" aria-label="Permalink to &quot;余额不足或消耗异常&quot;">​</a></h2><p>处理方式：</p><ol><li>到 <code>Wallet</code> 查看余额。</li><li>到 <code>Usage Logs</code> 查看是哪一个模型和 API Key 产生消耗。</li><li>给测试 Key 设置较低额度。</li><li>减少上下文长度和最大输出长度。</li></ol><h2 id="请求很慢或超时" tabindex="-1">请求很慢或超时 <a class="header-anchor" href="#请求很慢或超时" aria-label="Permalink to &quot;请求很慢或超时&quot;">​</a></h2><p>可能原因：</p><ul><li>选择了高推理或长上下文模型。</li><li>输入上下文太长。</li><li>客户端网络到 DouDi.ai 不稳定。</li><li>工具重试次数太少或超时时间太短。</li></ul><p>处理方式：</p><ul><li>先用短问题测试连通性。</li><li>换用轻量模型。</li><li>降低上下文长度。</li><li>适当增加客户端超时时间。</li></ul><h2 id="codex-频繁-reconnect" tabindex="-1">Codex 频繁 Reconnect <a class="header-anchor" href="#codex-频繁-reconnect" aria-label="Permalink to &quot;Codex 频繁 Reconnect&quot;">​</a></h2><p>如果 Codex Desktop 或 Codex CLI 经常显示 <code>Reconnect</code>，通常先排查本机代理。很多时候浏览器能访问网络，但 Codex 进程没有拿到代理环境变量，导致连接反复断开。</p><p>处理方式：</p><ol><li>打开你的代理软件，确认当前 HTTP 端口或 mixed 端口。</li><li>创建或编辑 <code>~/.codex/.env</code>。</li><li>写入下面两行，把端口替换成实际端口。</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">HTTP_PROXY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http://127.0.0.1:&lt;HTTP 或 mixed 端口&gt;&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">HTTPS_PROXY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http://127.0.0.1:&lt;HTTP 或 mixed 端口&gt;&quot;</span></span></code></pre></div><p>Windows 上通常对应：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>C:\\Users\\你的用户名\\.codex\\.env</span></span></code></pre></div><p>注意事项：</p><ul><li>不要固定照抄 <code>7890</code>、<code>7897</code> 等示例端口，以代理软件实际显示为准。</li><li>如果 <code>.env</code> 已存在，只追加或更新代理行，保留其他配置。</li><li>写入后需要完全退出并重启 Codex Desktop。</li><li>如果仍然重连，确认代理软件已开启 HTTP/mixed 入站，并允许本机 <code>127.0.0.1</code> 连接。</li></ul><h2 id="_503-no-available-oauth-accounts-in-pool" tabindex="-1">503 No available OAuth accounts in pool <a class="header-anchor" href="#_503-no-available-oauth-accounts-in-pool" aria-label="Permalink to &quot;503 No available OAuth accounts in pool&quot;">​</a></h2><p>如果报错里出现 <code>503 Service Unavailable</code> 和 <code>No available OAuth accounts in pool</code>，这通常是 OAuth 账号池不可用，不是模型配置错误。</p><p>处理方式：</p><ol><li>先确认你是否在用 OAuth 登录模式。</li><li>如果可以切换，改用 API Key / OpenAI Compatible 模式。</li><li>如果必须用 OAuth，先退出再重新登录一次。</li><li>稍后重试，很多时候是账号池临时耗尽。</li><li>如果你是自建或团队环境的维护者，检查账号池里是否还有可用 OAuth 账号，是否有人掉线、失效、限流或需要重新授权。</li></ol><p>判断建议：</p><ul><li>这个错误和代理端口不一定相关。</li><li>它更像认证池资源耗尽，而不是接口地址写错。</li><li>如果同时还有 401 / 403，再分别检查 Key、权限和网络。</li></ul>`,46)])])}const b=e(o,[["render",d]]);export{u as __pageData,b as default};
